using MessagePack.SourceGenerator;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class GeneratedFormatterRequirementGapTests(ITestOutputHelper logger)
{
    private const string ProjectBSource = """
        using MessagePack;
        using MessagePack.Formatters;

        namespace ProjectB
        {
            [GeneratedMessagePackResolver]
            partial class MyResolver { }

            [GeneratedMessagePackFormatter]
            public partial class MyObjectFormatter : IMessagePackFormatter<ProjectA.MyObject>
            {
            }
        }
        """;

    [Fact]
    public async Task PublicMutableFieldOfReferencedTypeIsSerialized()
    {
        string projectASource = """
            namespace ProjectA
            {
                public class MyObject
                {
                    public int DistinctiveField;

                    public int DistinctiveProperty { get; set; }
                }
            }
            """;

        GeneratorRun run = await this.RunAsync(projectASource, projectAReferencesMessagePack: false);
        Assert.True(run.Errors.Length == 0, string.Join(Environment.NewLine, run.Errors.Select(d => d.ToString())));
        Assert.Contains("DistinctiveProperty", run.GeneratedText);
        Assert.Contains("DistinctiveField", run.GeneratedText);
    }

    [Fact]
    public async Task MessagePackAttributesOnReferencedTypeAreHonoured()
    {
        string projectASource = """
            using MessagePack;

            namespace ProjectA
            {
                [MessagePackObject]
                public class MyObject
                {
                    [Key(0)]
                    public int DistinctiveId { get; set; }

                    [IgnoreMember]
                    public string DistinctiveSecret { get; set; }
                }
            }
            """;

        GeneratorRun run = await this.RunAsync(projectASource, projectAReferencesMessagePack: true);
        Assert.True(run.Errors.Length == 0, string.Join(Environment.NewLine, run.Errors.Select(d => d.ToString())));
        Assert.Contains("DistinctiveId", run.GeneratedText);
        Assert.DoesNotContain("DistinctiveSecret", run.GeneratedText);
    }

    private async Task<GeneratorRun> RunAsync(string projectASource, bool projectAReferencesMessagePack)
    {
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> messagePack = new(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        CSharpParseOptions parseOptions = new(LanguageVersion.Latest);

        List<MetadataReference> projectARefs = new(framework);
        if (projectAReferencesMessagePack)
        {
            projectARefs.AddRange(messagePack);
        }

        CSharpCompilation projectA = CSharpCompilation.Create(
            "ProjectA",
            new[] { CSharpSyntaxTree.ParseText(projectASource, parseOptions) },
            projectARefs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        using MemoryStream stream = new();
        var emitResult = projectA.Emit(stream);
        Assert.True(emitResult.Success, string.Join(Environment.NewLine, emitResult.Diagnostics.Select(d => d.ToString())));
        MetadataReference projectARef = MetadataReference.CreateFromImage(stream.ToArray());

        List<MetadataReference> projectBRefs = new(framework);
        projectBRefs.AddRange(messagePack);
        projectBRefs.Add(projectARef);
        CSharpCompilation projectB = CSharpCompilation.Create(
            "ProjectB",
            new[] { CSharpSyntaxTree.ParseText(ProjectBSource, parseOptions) },
            projectBRefs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new ISourceGenerator[] { new MessagePackGenerator().AsSourceGenerator() }, parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(projectB, out Compilation output, out ImmutableArray<Diagnostic> generatorDiagnostics);
        string generated = string.Join("\n", driver.GetRunResult().GeneratedTrees.Select(t => t.ToString()));
        logger.WriteLine(generated);

        ImmutableArray<Diagnostic> errors = output.GetDiagnostics()
            .Concat(generatorDiagnostics)
            .Where(d => d.Severity == DiagnosticSeverity.Error)
            .ToImmutableArray();
        foreach (Diagnostic d in errors)
        {
            logger.WriteLine(d.ToString());
        }

        return new GeneratorRun(errors, generated);
    }

    private sealed record GeneratorRun(ImmutableArray<Diagnostic> Errors, string GeneratedText);
}
